{
  "name": "@fellow99/opencode-feishu",
  "version": "1.7.4",
  "private": false,
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "description": "OpenCode 飞书插件 — 通过飞书 WebSocket 长连接接入 OpenCode AI 对话",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "skills",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build && npm run typecheck",
    "release": "bumpp"
  },
  "author": "fellow99",
  "repository": {
    "type": "git",
    "url": "https://github.com/fellow99/opencode-feishu"
  },
  "homepage": "https://github.com/fellow99/opencode-feishu#readme",
  "dependencies": {
    "@larksuiteoapi/node-sdk": "^1.56.1",
    "https-proxy-agent": "^7.0.6",
    "zod": "^4.3.6"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.1.0",
    "@opencode-ai/sdk": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.53",
    "@types/node": "^22.0.0",
    "bumpp": "^10.4.1",
    "tsup": "^8.0.0",
    "typescript": "^5.5.0"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "feishu",
    "lark",
    "飞书",
    "飞书机器人",
    "ai",
    "chatbot"
  ],
  "license": "MIT"
}
